 const OSM_CSS=String.raw`*{box-sizing:border-box}html,body{height:100%;margin:0;font:13px "Segoe UI",Tahoma,Arial,sans-serif;color:#222}body{display:flex}
#pn{width:290px;flex:none;display:flex;flex-direction:column;background:#fff;border-right:1px solid #d1d5db;min-height:0}#pn h1{margin:0;padding:10px 12px;font-size:15px;background:#7ebc6f;color:#fff}
#sf{display:flex;gap:4px;padding:8px}#sf input{flex:1;min-width:0;padding:7px 9px;border:1px solid #bbb;border-radius:4px;font:inherit}button{padding:6px 9px;border:1px solid #9ca3af;background:#f9fafb;border-radius:4px;cursor:pointer;font:inherit}button.p{background:#4c9a3c;color:#fff;border-color:#4c9a3c}
#rs{flex:1;overflow:auto;min-height:0}.r{padding:8px 12px;border-top:1px solid #eee;cursor:pointer}.r:hover{background:#eef6ec}.r b{display:block}.r small{color:#6b7280}#in{padding:8px 12px;border-top:1px solid #d1d5db;background:#f9fafb;font-size:12px;word-break:break-word}#in .bt{display:flex;flex-wrap:wrap;gap:4px;margin-top:6px}
#mw{flex:1;position:relative;min-width:0}#map{position:absolute;inset:0;overflow:hidden;background:#aad3df;touch-action:none;cursor:grab;user-select:none}#map.dr{cursor:grabbing}#tl{position:absolute;left:0;top:0;width:0;height:0}#tl img{position:absolute;width:256px;height:256px;user-select:none;-webkit-user-drag:none;pointer-events:none}
#mk{position:absolute;width:26px;height:36px;margin:-34px 0 0 -13px;display:none;pointer-events:none;filter:drop-shadow(0 2px 2px #0006)}
#zc{position:absolute;right:10px;top:10px;display:flex;flex-direction:column;gap:2px}#zc button{width:34px;height:34px;font-size:18px;padding:0;background:#fff}#ly{position:absolute;right:10px;top:116px;max-width:150px}
#at{position:absolute;right:0;bottom:0;background:#fffc;padding:2px 8px;font-size:11px}#at a{color:#0645ad}#sc{position:absolute;left:10px;bottom:22px;font-size:11px;border:2px solid #333;border-top:0;padding:0 4px;background:#fffa;white-space:nowrap}#co{position:absolute;left:10px;bottom:2px;font-size:11px;background:#fffc;padding:1px 6px}
#er{position:absolute;left:50%;top:12px;transform:translateX(-50%);background:#fef2f2;color:#991b1b;border:1px solid #fca5a5;border-radius:6px;padding:6px 12px;display:none;max-width:80%}
@media(max-width:640px){body{flex-direction:column}#pn{width:auto;height:44%;border-right:0;border-bottom:1px solid #d1d5db}}`;
