var layer='std',z=INIT.z||2,cx=0,cy=0,W=1,H=1,tiles={},loaded=0,failed=0,pin=null;
function esc(s){return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;')}
