 var c=center();$('co').textContent=c.lat.toFixed(5)+', '+c.lon.toFixed(5)+'  ·  zoom '+z;$('at').innerHTML=LAY[layer][3];
 var mpp=156543.03392*Math.cos(c.lat*Math.PI/180)/Math.pow(2,z),tg=[1,2,5,10,20,50,100,200,500,1000,2000,5000,10000,20000,50000,100000,200000,500000,1000000,2000000,5000000],d=tg[0];for(var i=0;i<tg.length;i++){if(tg[i]/mpp<=130)d=tg[i]}
