mp.addEventListener('pointermove',function(e){if(!dr)return;var dx=e.clientX-dr.x,dy=e.clientY-dr.y;if(Math.abs(dx)+Math.abs(dy)>4)moved=1;if(moved){cx=dr.cx-dx;cy=dr.cy-dy;render()}});
