 function wikiHost(x){let h=x.hostname.toLowerCase().replace(/^m\./,'').replace(/\.m\./,'.');if(h=='wikipedia.org'||h=='www.wikipedia.org')h='en.wikipedia.org';return/^([a-z-]+\.)?(wikipedia|wiktionary|wikibooks|wikiquote|wikisource|wikinews|wikiversity)\.org$|^(commons|meta|species)\.wikimedia\.org$/.test(h)?h:null}
