   const sp=x.searchParams;let m=(x.hash||'').match(/map=(\d+)\/(-?[\d.]+)\/(-?[\d.]+)/);if(m){init.z=+m[1];init.lat=+m[2];init.lon=+m[3]}
   if(sp.get('mlat')&&sp.get('mlon')){init.pin=1;init.lat=+sp.get('mlat');init.lon=+sp.get('mlon');if(init.z==null)init.z=+sp.get('zoom')||15}
   if(sp.get('query'))init.q=sp.get('query');else if(sp.get('q'))init.q=sp.get('q');
