 function ensureBlock(){if(!ed.firstChild||(ed.childNodes.length==1&&ed.firstChild.nodeName=='BR')){ed.innerHTML='<p><br></p>'}}
 const blockSel='p,h1,h2,h3,h4,h5,h6,li,blockquote,pre';
 function blocks(){const s=sel();if(!s.rangeCount)return[];const r=s.getRangeAt(0);if(!ed.contains(r.commonAncestorContainer))return[];const out=[];ed.querySelectorAll(blockSel+',td,th').forEach(b=>{if(r.intersectsNode(b)&&!b.closest('.wp-fnl'))out.push(b)});
  if(!out.length){let n=r.startContainer;while(n&&n!==ed&&!(n.nodeType==1&&/^(P|H[1-6]|LI|BLOCKQUOTE|PRE|DIV|TD|TH)$/.test(n.tagName)))n=n.parentNode;if(n&&n!==ed)out.push(n)}
  return out.filter(b=>!out.some(o=>o!==b&&b.contains(o)))}
