 function outlineUpd(){if(!outline)return;const L=q('.wp-nl');L.innerHTML='';ed.querySelectorAll('h1,h2,h3,h4').forEach((h,i)=>{if(h.closest('.wp-toc'))return;const d=document.createElement('div');d.className='wp-ni l'+h.tagName[1];d.textContent=h.textContent||'(empty heading)';d.onclick=()=>{h.scrollIntoView({block:'start',behavior:'smooth'});const r=document.createRange();r.selectNodeContents(h);r.collapse(true);sel().removeAllRanges();sel().addRange(r);ed.focus()};L.appendChild(d)});if(!L.children.length)L.innerHTML='<div class="wp-ni" style="color:#6b7280">No headings yet. Use the Style box to make Heading 1–4.</div>'}
