 function insertTable(r,c,hdrRow,border){let h=`<table class='wp-t${border?'':' nb'}'><tbody>`;for(let i=0;i<r;i++){h+='<tr>';for(let j=0;j<c;j++)h+=(i==0&&hdrRow?'<th>':'<td>')+'<br>'+(i==0&&hdrRow?'</th>':'</td>');h+='</tr>'}h+='</tbody></table><p><br></p>';const before=new Set(ed.querySelectorAll('table'));insertHTML(h);const nt=[...ed.querySelectorAll('table')].find(t=>!before.has(t));if(nt){const c=nt.querySelector('th,td');const r=document.createRange();r.setStart(c,0);r.collapse(true);sel().removeAllRanges();sel().addRange(r)}}
 const cell=()=>{const s=sel();let n=s.anchorNode;while(n&&n!==ed){if(n.nodeType==1&&/^(TD|TH)$/.test(n.tagName))return n;n=n.parentNode}return null};
 function tbl(act,arg){rs();const c=cell();if(!c)return say('Click inside a table cell first.');const tr=c.parentElement,t=c.closest('table'),idx=[...tr.children].indexOf(c);
  if(act=='rowA'||act=='rowB'){const n=tr.cloneNode(true);[...n.children].forEach(x=>x.innerHTML='<br>');tr.parentElement.insertBefore(n,act=='rowA'?tr:tr.nextSibling)}
  else if(act=='colL'||act=='colR'){[...t.rows].forEach(r=>{const ref=r.children[idx]||r.lastElementChild,n=document.createElement(ref.tagName);n.innerHTML='<br>';r.insertBefore(n,act=='colL'?ref:ref.nextSibling)})}
  else if(act=='delRow'){if(t.rows.length<2)t.remove();else tr.remove()}
  else if(act=='delCol'){if(tr.children.length<2)t.remove();else [...t.rows].forEach(r=>r.children[idx]&&r.children[idx].remove())}
  else if(act=='delTbl')t.remove();
  else if(act=='merge'){const n=c.nextElementSibling;if(!n)return say('No cell to the right.');c.colSpan=(c.colSpan||1)+(n.colSpan||1);c.innerHTML=(c.innerHTML+' '+n.innerHTML).replace(/<br>/g,'')||'<br>';n.remove()}
  else if(act=='shade')c.style.background=arg;
  else if(act=='borders')t.classList.toggle('nb');
  else if(act=='hdr'){const f=t.rows[0];[...f.children].forEach(x=>{const n=document.createElement(x.tagName=='TH'?'td':'th');n.innerHTML=x.innerHTML;n.colSpan=x.colSpan;f.replaceChild(n,x)})}
  touch();sched()}
 function imgDialog(){dialog('Insert picture',`<div style='display:grid;grid-template-columns:90px 1fr;gap:8px;align-items:center'><label>From computer</label><input type='file' accept='image/*' class='pf'><label>Web address</label><input class='pu' placeholder='https://example.com/photo.jpg'><label>Description</label><input class='pa' placeholder='Alt text (optional)'></div>`,[['Cancel'],['Insert',o=>{const f=o.querySelector('.pf').files[0],u=o.querySelector('.pu').value.trim(),alt=esc(o.querySelector('.pa').value);if(u&&window.__sys){const g=fwCheck(u);if(g){say('Blocked by the firewall: '+g.why);return false}}
   if(f)readImg(f,d=>insertHTML(`<img src="${d}" alt="${alt}" style="max-width:100%">`));else if(/^https?:\/\//i.test(u))insertHTML(`<img src="${esc(u)}" alt="${alt}" style="max-width:100%">`);else{say('Choose a file or enter a web address.');return false}},1]])}
 function readImg(f,cb){if(!/^image\//.test(f.type))return say('That is not an image file.');const fr=new FileReader();fr.onload=()=>{const im=new Image();im.onload=()=>{const M=1000,k=Math.min(1,M/Math.max(im.width,im.height));if(k==1&&f.size<250000){cb(fr.result);return}const c=document.createElement('canvas');c.width=Math.round(im.width*k);c.height=Math.round(im.height*k);const g=c.getContext('2d');if(f.type!='image/png'){g.fillStyle='#fff';g.fillRect(0,0,c.width,c.height)}g.drawImage(im,0,0,c.width,c.height);cb(c.toDataURL(f.type=='image/png'?'image/png':'image/jpeg',.85))};im.onerror=()=>say('Could not read that image.');im.src=fr.result};fr.readAsDataURL(f)}
 function linkDialog(){if(typeof wplDialog=='function'&&W.X)return wplDialog(W.X);rs();const s=sel(),txt=s.toString();let a=s.anchorNode;while(a&&a!==ed&&!(a.nodeType==1&&a.tagName=='A'))a=a.parentNode;const cur=a&&a.tagName=='A'?a:null;
  dialog('Hyperlink',`<div style='display:grid;grid-template-columns:90px 1fr;gap:8px;align-items:center'><label>Text</label><input class='lt' value="${esc(cur?cur.textContent:txt)}"><label>Address</label><input class='lu' value="${esc(cur?cur.getAttribute('href'):'https://')}"></div>`,[['Cancel'],...(cur?[['Remove link',()=>{rs();document.execCommand('unlink');touch()}]]:[]),['OK',o=>{let u=o.querySelector('.lu').value.trim(),t=o.querySelector('.lt').value||u;if(!u||u=='https://')return false;if(!/^(https?:|mailto:|#|file:)/i.test(u))u='https://'+u;rs();if(cur){cur.href=u;cur.textContent=t}else document.execCommand('insertHTML',false,`<a href="${esc(u)}">${esc(t)}</a>`);touch()},1]])}
 function specialDlg(){dialog('Special characters',`<div class='wp-chars'>${WP_CHARS.map(c=>`<button>${c}</button>`).join('')}</div>`,[['Close']],o=>{o.querySelector('.wp-chars').onclick=e=>{if(e.target.tagName=='BUTTON'){rs();document.execCommand('insertText',false,e.target.textContent);touch()}}})}
 function tableDlg(){dialog('Insert table',`<div style='display:grid;grid-template-columns:110px 80px;gap:8px;align-items:center'><label>Rows</label><input type='number' class='tr' value='3' min='1' max='50'><label>Columns</label><input type='number' class='tc' value='3' min='1' max='20'><label>Header row</label><input type='checkbox' class='th' checked><label>Borders</label><input type='checkbox' class='tb' checked></div>`,[['Cancel'],['Insert',o=>{const r=Math.max(1,Math.min(50,+o.querySelector('.tr').value||3)),c=Math.max(1,Math.min(20,+o.querySelector('.tc').value||3));insertTable(r,c,o.querySelector('.th').checked,o.querySelector('.tb').checked)},1]])}
 function paraDlg(){const b=blocks()[0];const cs=b?getComputedStyle(b):{};dialog('Paragraph',`<div style='display:grid;grid-template-columns:130px 1fr;gap:8px;align-items:center'><label>Alignment</label><select class='pa'><option value=''>(unchanged)</option><option>left</option><option>center</option><option>right</option><option>justify</option></select><label>Line spacing</label><select class='pl'><option value=''>(unchanged)</option><option>1</option><option>1.15</option><option>1.5</option><option>2</option></select><label>Space before (pt)</label><input type='number' class='pb' min='0' max='144' placeholder='unchanged'><label>Space after (pt)</label><input type='number' class='pf' min='0' max='144' placeholder='unchanged'><label>Left indent (in)</label><input type='number' class='pi' step='0.25' min='0' max='6' placeholder='unchanged'><label>First line indent (in)</label><input type='number' class='pn' step='0.25' min='-3' max='6' placeholder='unchanged'></div>`,[['Cancel'],['OK',o=>{rs();const g=c=>o.querySelector(c).value;blocks().forEach(b=>{if(g('.pa'))b.style.textAlign=g('.pa');if(g('.pl'))b.style.lineHeight=g('.pl');if(g('.pb')!=='')b.style.marginTop=g('.pb')+'pt';if(g('.pf')!=='')b.style.marginBottom=g('.pf')+'pt';if(g('.pi')!=='')b.style.marginLeft=g('.pi')+'in';if(g('.pn')!=='')b.style.textIndent=g('.pn')+'in'});touch();sched()},1]])}
 function setupDlg(){dialog('Page setup',`<div style='display:grid;grid-template-columns:110px 1fr;gap:8px;align-items:center'><label>Paper size</label><select class='ps'>${Object.keys(WP_SIZES).map(k=>`<option${k==meta.size?' selected':''}>${k}</option>`).join('')}</select><label>Orientation</label><select class='po'><option value='0'${meta.land?'':' selected'}>Portrait</option><option value='1'${meta.land?' selected':''}>Landscape</option></select><label>Margins (inches)</label><div><input type='number' class='mt' step='0.25' min='0.25' max='3' value='${meta.m.t}' style='width:60px' title='Top'> <input type='number' class='mb' step='0.25' min='0.25' max='3' value='${meta.m.b}' style='width:60px' title='Bottom'> <input type='number' class='ml' step='0.25' min='0.25' max='3' value='${meta.m.l}' style='width:60px' title='Left'> <input type='number' class='mr' step='0.25' min='0.25' max='3' value='${meta.m.r}' style='width:60px' title='Right'><div style='font-size:11px;color:#6b7280'>top · bottom · left · right</div></div><label>Columns</label><select class='pc'><option>1</option><option>2</option><option>3</option></select></div>`,[['Cancel'],['OK',o=>{const g=c=>o.querySelector(c).value,n=c=>Math.max(.25,Math.min(3,+g(c)||1));meta.size=g('.ps');meta.land=g('.po')=='1';meta.m={t:n('.mt'),b:n('.mb'),l:n('.ml'),r:n('.mr')};ed.style.columnCount=g('.pc')>1?g('.pc'):'';ed.style.columnGap='24px';touch();layout()},1]],o=>{o.querySelector('.pc').value=ed.style.columnCount||'1'})}
 function hfDlg(){dialog('Header and footer',`<div style='display:grid;grid-template-columns:70px 1fr;gap:8px;align-items:center'><label>Header</label><input class='hh' value="${esc(meta.hdr)}" placeholder='Text at the top of every page'><label>Footer</label><input class='hf' value="${esc(meta.ftr)}" placeholder='Text at the bottom; {page} and {pages} work'><label></label><label><input type='checkbox' class='hp'${meta.pn?' checked':''}> Show “Page X of Y” in the footer</label></div>`,[['Cancel'],['OK',o=>{meta.hdr=o.querySelector('.hh').value;meta.ftr=o.querySelector('.hf').value;meta.pn=o.querySelector('.hp').checked;touch();layout()},1]])}
 function statsDlg(){const t=docText(),w=words(t),ch=t.replace(/\n/g,'').length,nsp=t.replace(/\s/g,'').length,sen=(t.match(/[^.!?]+[.!?]+(\s|$)/g)||(w?[t]:[])).length,para=ed.querySelectorAll('p,li,h1,h2,h3,h4,blockquote').length;const syl=(t.toLowerCase().match(/[aeiouy]+/g)||[]).length||1;const fre=w&&sen?206.835-1.015*(w/sen)-84.6*(syl/w):0;const gl=w&&sen?.39*(w/sen)+11.8*(syl/w)-15.59:0;
  info('Document statistics',`<table class='wp-stt'><tr><td>Pages</td><td>${W.pages||1}</td></tr><tr><td>Words</td><td>${w}</td></tr><tr><td>Characters (with spaces)</td><td>${ch}</td></tr><tr><td>Characters (no spaces)</td><td>${nsp}</td></tr><tr><td>Sentences</td><td>${sen}</td></tr><tr><td>Paragraphs</td><td>${para}</td></tr><tr><td>Average word length</td><td>${w?(nsp/w).toFixed(1):0}</td></tr><tr><td>Reading time</td><td>${Math.max(w?1:0,Math.round(w/230))} min</td></tr><tr><td>Reading ease (Flesch)</td><td>${w>5?Math.max(0,Math.min(100,fre)).toFixed(0):'n/a'}</td></tr><tr><td>Grade level</td><td>${w>5?Math.max(0,gl).toFixed(1):'n/a'}</td></tr></table>`)}
 /* ---------- TOC + footnotes ---------- */
 function tocHTML(){const hs=[...ed.querySelectorAll('h1,h2,h3,h4')].filter(h=>!h.closest('.wp-toc'));hs.forEach((h,i)=>{if(!h.id||!/^wp-h/.test(h.id))h.id='wp-h'+i+'-'+Math.random().toString(36).slice(2,6)});
  return`<div class='wp-toc' contenteditable='false'><p class='wp-toc-t'>Table of Contents</p>${hs.length?hs.map(h=>`<p style='margin:2pt 0 2pt ${(+h.tagName[1]-1)*16}px'><a href='#${h.id}'>${esc(h.textContent)}</a></p>`).join(''):'<p><i>No headings found. Apply Heading 1–4 styles, then update this table.</i></p>'}</div>`}
