 function ask(){const el=say('Ask me a question, like “how do I add a table?”',[],{});const t=el.querySelector('.wn-t');t.insertAdjacentHTML('beforeend',`<input class='wn-q' placeholder='Type your question…'><div class='wn-res'></div>`);const inp=t.querySelector('.wn-q'),res=t.querySelector('.wn-res');inp.focus();
  const run=()=>{const w=inp.value.toLowerCase().split(/[^a-z0-9]+/).filter(x=>x.length>2&&!/^(how|can|the|and|you|for|what|does|with|make|get|want|use|add|do|to|my|i)$/.test(x));res.innerHTML='';if(!w.length)return;const sc=KB.map(e=>{const k=e[0].split(' ');let s=0;w.forEach(x=>{k.forEach(y=>{if(y==x)s+=3;else if(y.startsWith(x)||x.startsWith(y)&&y.length>3)s+=1.5})});return[s,e]}).filter(x=>x[0]>0).sort((a,b)=>b[0]-a[0]).slice(0,3);
   if(!sc.length){res.innerHTML='<div class="wn-fi">I’m not sure about that one. Try words like “table”, “margins”, “save”, “heading” or “print”.</div>';return}
   sc.forEach(([s,e])=>{const d=document.createElement('div');d.className='wn-fi';d.innerHTML=`<div>${e[1]}</div>`;if(e[2]){const b=document.createElement('button');b.textContent='Show me';b.onclick=()=>{hide();e[2]()};d.appendChild(b)}res.appendChild(d)})};
  inp.onkeydown=e=>{if(e.key=='Enter')run();e.stopPropagation()};const b=document.createElement('button');b.textContent='Ask';b.className='p';b.onclick=run;el.querySelector('.wn-b').appendChild(b);const c=document.createElement('button');c.textContent='Close';c.onclick=hide;el.querySelector('.wn-b').appendChild(c)}
