 let dragMoved=0;m.addEventListener('click',()=>{if(dragMoved){dragMoved=0;return}if(box.classList.contains('sleep')){mood('wave',1500)}if(mode=='open')hide();else menu()});
 (function(){let d=null;m.addEventListener('pointerdown',e=>{const r=box.getBoundingClientRect(),rr=root.getBoundingClientRect();d={x:e.clientX,y:e.clientY,l:r.left-rr.left,t:r.top-rr.top};m.setPointerCapture(e.pointerId)});
  m.addEventListener('pointermove',e=>{if(!d)return;const dx=e.clientX-d.x,dy=e.clientY-d.y;if(Math.abs(dx)+Math.abs(dy)<5&&!dragMoved)return;dragMoved=1;box.style.right='auto';box.style.bottom='auto';box.style.left=Math.max(0,Math.min(root.clientWidth-box.offsetWidth,d.l+dx))+'px';box.style.top=Math.max(0,Math.min(root.clientHeight-box.offsetHeight,d.t+dy))+'px'});
  const up=()=>{d=null;setTimeout(()=>{dragMoved=0},0)};m.addEventListener('pointerup',up);m.addEventListener('pointercancel',up)})();
 const eyes=()=>[...box.querySelectorAll('.wn-pl')];
 const onMove=e=>{if(!W.el.isConnected){document.removeEventListener('pointermove',onMove);return}const r=m.getBoundingClientRect(),cx=r.left+r.width/2,cy=r.top+r.height*.4,dx=e.clientX-cx,dy=e.clientY-cy,dd=Math.hypot(dx,dy)||1,k=Math.min(1,dd/200)*3.5;eyes().forEach(p=>{p.style.transform=`translate(${dx/dd*k}px,${dy/dd*k}px)`})};document.addEventListener('pointermove',onMove);
 const onEdit=()=>{clearTimeout(idleT);if(X.dirty&&!sinceDirty)sinceDirty=Date.now();if(!X.dirty)sinceDirty=0;box.classList.remove('sleep');idleT=setTimeout(auto,2200)};
