__LNR["LOC"]=(()=>{const l=LANGS.find(x=>x[0]==S.lang);return l?l[2]:undefined});
function trText(text,lang){const d=I18N[lang];if(!d)return null;const tt=text.trim();if(!tt)return null;let w=d[tt];if(w!=null){return text.slice(0,text.indexOf(tt))+w+text.slice(text.indexOf(tt)+tt.length)}
 const m=/^([^\p{L}\p{N}]*)([\s\S]*?)([^\p{L}\p{N}]*)$/u.exec(text);if(!m||!m[2])return null;w=d[m[2]];return w==null?null:m[1]+w+m[3]}
function trNode(n){const lang=TRX.lang;let rec=TRX.map.get(n);if(rec&&n.nodeValue!==rec.out){TRX.map.delete(n);rec=null}const src=rec?rec.src:n.nodeValue;
 if(lang=='en'){if(rec){n.nodeValue=rec.src;TRX.map.delete(n)}return}
 const p=n.parentElement;if(!p||p.closest(TRX.skip))return;const out=trText(src,lang);if(out!=null){if(n.nodeValue!==out)n.nodeValue=out;TRX.map.set(n,{src,out})}else if(rec){n.nodeValue=rec.src;TRX.map.delete(n)}}
function trAttrs(el){if(!el.getAttribute)return;['title','placeholder'].forEach(a=>{const v=el.getAttribute(a);const k='data-i18n-'+a;const src=el.hasAttribute(k)?el.getAttribute(k):v;if(v==null)return;
  if(TRX.lang=='en'){if(el.hasAttribute(k)){el.setAttribute(a,el.getAttribute(k));el.removeAttribute(k)}return}
  if(el.closest&&el.closest(TRX.skip))return;const out=trText(src,TRX.lang);if(out!=null){if(!el.hasAttribute(k))el.setAttribute(k,src);if(v!==out)el.setAttribute(a,out)}})}
function trTree(root){if(root.nodeType==3){trNode(root);return}if(root.nodeType!=1&&root.nodeType!=9)return;const w=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);let n;const L=[];while((n=w.nextNode()))L.push(n);L.forEach(trNode);if(root.nodeType==1)trAttrs(root);root.querySelectorAll&&root.querySelectorAll('[title],[placeholder],[data-i18n-title],[data-i18n-placeholder]').forEach(trAttrs)}
function setLang(l){if(TRX.lang==l)return;TRX.lang=l;document.documentElement.lang=l;for(const n of [...TRX.map.keys()])if(!n.isConnected)TRX.map.delete(n);trBusy=true;try{if(l=='en'){for(const [n,r] of [...TRX.map]){n.nodeValue=r.src}TRX.map.clear();document.querySelectorAll('[data-i18n-title],[data-i18n-placeholder]').forEach(trAttrs)}else{for(const [n,r] of [...TRX.map]){n.nodeValue=r.src}TRX.map.clear();trTree(document.body)}}finally{trBusy=false}}
