   {const rd=op&7,rs=(op>>>3)&7;let a=r[rd],b=r[rs],v;
    switch((op>>>6)&15){
     case 0:v=a&b;r[rd]=v;nz(v);return;case 1:v=a^b;r[rd]=v;nz(v);return;
     case 2:v=lsl(a,b&0xFF);r[rd]=v;nz(v);fC=shC;cyc++;return;
     case 3:v=lsr(a,b&0xFF);r[rd]=v;nz(v);fC=shC;cyc++;return;
     case 4:v=asr(a,b&0xFF);r[rd]=v;nz(v);fC=shC;cyc++;return;
     case 5:r[rd]=add(a,b,fC);return;case 6:r[rd]=sub(a,b,fC);return;
     case 7:v=ror(a,b&0xFF);r[rd]=v;nz(v);fC=shC;cyc++;return;
     case 8:nz(a&b);return;case 9:r[rd]=sub(0,b,1);return;case 10:sub(a,b,1);return;case 11:add(a,b,0);return;
     case 12:v=a|b;r[rd]=v;nz(v);return;case 13:v=Math.imul(a,b);r[rd]=v;nz(v);cyc+=mulCyc(a);return;
     case 14:v=a&~b;r[rd]=v;nz(v);return;case 15:v=~b;r[rd]=v;nz(v);return}}return;
