function diff8(s,d,vram){const h=rd32(s)>>>0,size=h>>>8;s=(s+4)|0;const out=new Uint8Array(size);let v=0;for(let i=0;i<size;i++){v=(v+rd8(s+i))&0xFF;out[i]=v}writeOut(d,out,vram)}
