const BLZD_ONE={busy:null};
blzdSend=async function(cmd,S,out){S=S||await blzdSettings(true);if(!S||!S.devlink||!S.devlinkToken){out&&(out.textContent='No development link is set (Settings › Apps › Blitzen › Developer).');return null}
 if(BLZD_ONE.busy){notify('One command at a time',`${BLZD_ONE.busy} is still waiting for the test computer: Blitzen sends the next one after its result.`);return null}
 const lines=[['Development link',S.devlink],['Command',cmd.kind=='sh'?'Run a command (sh)':cmd.kind=='get'?'Get a file':cmd.kind=='screenshot'?'Take a screenshot':String(cmd.kind)]];if(cmd.path)lines.push(['File',cmd.path]);
 const text=cmd.kind=='sh'?String(cmd.script||''):cmd.kind=='get'?String(cmd.path||''):JSON.stringify(cmd,null,1),sec=blzdSecret(JSON.stringify(cmd));
 if(sec){await blzdAllow('Send a command to the test computer',lines,text,{refuse:sec});out&&(out.textContent='Not sent: it carries '+sec+'.');return null}
 if(!await blzdAllow('Send a command to the test computer',lines,text,{risks:blzdRisks(cmd)})){out&&(out.textContent='Not sent.');return null}
 BLZD_ONE.busy='a command';
 try{let id;try{id=(await blzdApi('dl-send',JSON.stringify(cmd))).data.id}catch(e){out&&(out.textContent=e.message);return null}BLZD_ONE.busy=id;
  const t0=Date.now();for(;;){if(out)out.textContent=`Sent as ${id}. Waiting for the test computer… (${Math.round((Date.now()-t0)/1000)} s; with Ask first on, someone allows it there)`;
   let j;try{j=(await blzdApi('dl-wait?id='+id+'&secs=25')).data}catch(e){out&&(out.textContent=e.message);return null}
   if(j&&j.result)return{id,r:j.result};if(Date.now()-t0>30*60000){out&&(out.textContent=`No result for ${id} in 30 minutes.`);return null}}}
 finally{BLZD_ONE.busy=null}};
function blzdWfRisks(t){t=String(t||'');const r=[];
 if(/gh\s+release|action-gh-release|upload-release-asset|releases|gh-pages|pages|deploy|publish|npm\s+publish|docker\s+push|twine\s+upload/i.test(t))r.push('may publish something (a release, a page, a package)');
 if(/\$\{\{\s*secrets\./.test(t))r.push('uses the repository’s secrets');if(/permissions:\s*[^\n]*write|contents:\s*write/i.test(t))r.push('may change the repository (it asks for write access)');return r}
function blzdChangeCheck(path,a,b){const A=String(a).split('\n'),B=String(b).split('\n'),add=B.filter(x=>!A.includes(x)),gone=A.filter(x=>!B.includes(x)).length,r=[];
 if(gone>20)r.push(`removes ${gone} lines`);if(/^\.github\//.test(path))r.push('changes how the repository builds (its workflows)');
 if(/(^|\/)(keys?|secrets?)\/|\.(pem|key)$/i.test(path))r.push('is a file for keys');return{risks:r,refuse:blzdSecret(add.join('\n'))}}
{const st=document.createElement('style');st.textContent=`.blzdrisk{border:1px solid #c2410c;background:#c2410c18;padding:4px 8px;margin:6px 0}.blzdrisk ul{margin:4px 0 0 18px;padding:0}.blzdno{border:1px solid #b91c1c;padding:4px 8px}.blzdallow .blzdfull{max-height:340px;overflow:auto;white-space:pre}`;(document.head||document.documentElement).appendChild(st)}
const LAZY_DONE={},LAZY_P={};
let LAZY={"sheet": "a/50b4cdfa0349da7e.js", "deck": "a/94de9de26bc45ab3.js"};
function lazyApp(g){if(LAZY_DONE[g])return Promise.resolve();return LAZY_P[g]||(LAZY_P[g]=new Promise((res,rej)=>{const s=document.createElement('script');s.src=LAZY[g];s.async=false;
 s.onload=()=>LAZY_DONE[g]?res():(delete LAZY_P[g],rej(new Error('incomplete')));s.onerror=()=>{delete LAZY_P[g];s.remove();rej(new Error('not found'))};document.head.appendChild(s)}))}
function aBytes(u){const x=new XMLHttpRequest();x.open('GET',u,false);x.overrideMimeType('text/plain; charset=x-user-defined');x.send();if(x.status!=200)throw new Error(u+': '+(x.status||'not found'));
 const t=x.responseText,b=new Uint8Array(t.length);for(let i=0;i<t.length;i++)b[i]=t.charCodeAt(i)&255;return b}
async function aFetch(u){const r=await fetch(u);if(!r.ok)throw new Error(u+': '+r.status);return r}
function lazyFail(name,g,retry){try{notify(name+' could not be loaded','Its files could not be read ('+LAZY[g]+'). Try again, or restart if it keeps happening.',{kind:'error',action:retry})}catch(e){}}
async function sheetApp(...a){const me=sheetApp;try{await lazyApp('sheet')}catch(e){lazyFail('SpreadsheetPro','sheet',()=>sheetApp(...a));return null}if(sheetApp===me)throw new Error('SpreadsheetPro: not loaded');return sheetApp(...a)}
async function deckApp(...a){const me=deckApp;try{await lazyApp('deck')}catch(e){lazyFail('PresentPro','deck',()=>deckApp(...a));return null}if(deckApp===me)throw new Error('PresentPro: not loaded');return deckApp(...a)}
function volPop(){const old=document.querySelector('.vp');if(old){old.remove();return}const m=S.snd.master,B=$('#vol'),p=document.createElement('div');p.className='vp';
 p.innerHTML=`<div style='font-weight:700;margin-bottom:6px'>Volume</div><div style='display:flex;align-items:center;gap:8px'><input type='range' min='0' max='100' value='${m.vol}' style='flex:1;min-width:0'><span class='vpc' style='width:44px;text-align:right'>${m.on?m.vol+'%':'Muted'}</span></div><label style='display:block;margin-top:8px'><input type='checkbox'${m.on?'':' checked'}> Mute</label>`;
 document.body.appendChild(p);const r=B.getBoundingClientRect(),b=document.body.className;let x=r.left+r.width/2-p.offsetWidth/2,y=r.top-p.offsetHeight-8;
 if(/top/.test(b))y=r.bottom+8;if(/left/.test(b)){x=r.right+8;y=r.top}if(/right/.test(b)){x=r.left-p.offsetWidth-8;y=r.top}
 p.style.left=Math.max(4,Math.min(innerWidth-p.offsetWidth-4,x))+'px';p.style.top=Math.max(4,Math.min(innerHeight-p.offsetHeight-4,y))+'px';
 const rg=p.querySelector('input[type=range]'),mu=p.querySelector('input[type=checkbox]');
 rg.oninput=()=>{m.vol=+rg.value;m.on=m.vol>0;trayVol()};rg.onchange=()=>sfx('notify');
 mu.onchange=()=>{m.on=!mu.checked;if(m.on&&m.vol==0)m.vol=50;trayVol();if(m.on)sfx('notify')};
 const kill=e=>{if(!p.contains(e.target)&&!B.contains(e.target)){p.remove();document.removeEventListener('pointerdown',kill,true)}};setTimeout(()=>document.addEventListener('pointerdown',kill,true),0)}